    def test_leading_and_trailing_spaces(self):
        self.assertEqual(words_string("  hello world  "), ["hello", "world"])

    def test_leading_and_trailing_commas(self):
        self.assertEqual(words_string(",hello,world,"), ["hello", "world"])

    def test_only_commas(self):
        self.assertEqual(words_string(",,,,"), [])

    def test_only_spaces(self):
        self.assertEqual(words_string("     "), [])

    def test_consecutive_commas(self):
        self.assertEqual(words_string("a,,b"), ["a", "b"])

    def test_special_characters(self):
        self.assertEqual(words_string("a1,b2,c3"), ["a1", "b2", "c3"])

    def test_numbers_as_string(self):
        self.assertEqual(words_string("1,2,3"), ["1", "2", "3"])

    def test_comma_with_space_after(self):
        self.assertEqual(words_string("apple, banana, cherry"), ["apple", "banana", "cherry"])


